{"filePath":"/tmp/check-layout.js","content":"async (page) => {
  const figs = await page.$$eval('figure.am-flow', (nodes) => nodes.map((f) => {
    const svg = f.querySelector('svg');
    const box = svg.getBoundingClientRect();
    const labels = [...svg.querySelectorAll('text')].map(t => {
      const r = t.getBoundingClientRect();
      return { t: t.textContent.trim(), x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) };
    });
    // overlap among labels that are short node names vs edge labels - check any text overlap
    const overlaps = [];
    for (let i = 0; i < labels.length; i++) {
      for (let j = i + 1; j < labels.length; j++) {
        const a = labels[i], b = labels[j];
        if (!a.t || !b.t) continue;
        const ix = Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x);
        const iy = Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y);
        if (ix > 4 && iy > 4) overlaps.push([a.t, b.t, ix, iy]);
      }
    }
    return {
      aria: svg.getAttribute('aria-label'),
      viewBox: svg.getAttribute('viewBox'),
      box: { w: Math.round(box.width), h: Math.round(box.height) },
      overflow: box.width > (f.getBoundingClientRect().width + 2),
      overlaps: overlaps.slice(0, 20),
      overlapCount: overlaps.length,
    };
  }));
  const panelOverflow = await page.$$eval('.am-panel', (nodes) => nodes.map(n => {
    const id = n.querySelector('.am-panel-title, h2, .am-kicker')?.textContent?.slice(0, 20);
    return { id, sw: n.scrollWidth, cw: n.clientWidth, sh: n.scrollHeight, ch: n.clientHeight };
  }));
  return { figs, panelOverflow };
}
"}

{"filePath":"/tmp/check-layout.js","content":"async (page) => {
  return await page.evaluate(() => {
    const svgs = [...document.querySelectorAll('svg[aria-label]')];
    return svgs.map((svg) => {
      const box = svg.getBoundingClientRect();
      const parent = svg.closest('figure, .am-panel-body, .am-panel');
      const pb = parent.getBoundingClientRect();
      const texts = [...svg.querySelectorAll('text')].map(t => {
        const r = t.getBoundingClientRect();
        return { t: (t.textContent || '').trim(), x: r.x, y: r.y, w: r.width, h: r.height };
      }).filter(t => t.t && t.w > 0);
      const overlaps = [];
      for (let i = 0; i < texts.length; i++) {
        for (let j = i + 1; j < texts.length; j++) {
          const a = texts[i], b = texts[j];
          const ix = Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x);
          const iy = Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y);
          if (ix > 3 && iy > 3) overlaps.push(a.t + ' ∩ ' + b.t);
        }
      }
      const clipped = texts.filter(t => t.x < pb.x - 1 || t.y < pb.y - 1 || t.x + t.w > pb.x + pb.width + 1 || t.y + t.h > pb.y + pb.height + 1)
        .map(t => t.t);
      return {
        aria: svg.getAttribute('aria-label'),
        viewBox: svg.getAttribute('viewBox'),
        rendered: { w: Math.round(box.width), h: Math.round(box.height) },
        parent: { w: Math.round(pb.width), h: Math.round(pb.height) },
        textCount: texts.length,
        overlapCount: overlaps.length,
        overlaps: overlaps.slice(0, 12),
        clipped,
      };
    });
  });
}
"}

