    const title = await panels.nth(i).locator('h2, .am-panel-title').first().innerText().catch(() => String(i));
    const safe = title.replace(/[^\w\u4e00-\u9fff]+/g, '_').slice(0, 20);
    await panels.nth(i).screenshot({ path: `/tmp/panel-${i}-${safe}.png` });
  }
  return { n };
}
